import { zodToJsonSchema } from 'zod-to-json-schema';
import { tiktokAuthSchema, tiktokChannelSchema, tiktokPublishSchema, tiktokStatusSchema, tiktokUploadSchema, tiktokVideosSchema } from './tiktok-client.js';
const definitions = [
    { name: 'tiktok_auth', title: 'Connect a TikTok channel', schema: tiktokAuthSchema, readOnly: false,
        description: 'Start or inspect Desktop Login Kit OAuth for one channel. Reads client_key/client_secret/redirect_uri from SNS_TOKEN_DIR/[channel]/tiktok-client.json; accepts no secrets. start returns an authorization URL and listens on the registered 127.0.0.1 port for 10 minutes using state and TikTok PKCE. Keep this MCP process alive while the user logs in and consents. Verifies expectedHandle and existing open_id before atomically saving tiktok-oauth.json (0600). status returns progress, scopes and live account check without tokens. App/product/scope approval is external; browser login alone is not API authorization. Does not publish. Missing credentials, account mismatch, rejected consent or occupied port fail without replacing the account.' },
    { name: 'tiktok_creator_info', title: 'Inspect TikTok posting choices', schema: tiktokChannelSchema, readOnly: true,
        description: 'Read current TikTok creator info and account identity before preparing Direct Post. Requires video.publish. Returns creator nickname/avatar, allowed privacy levels, interaction restrictions and max duration. Show these to the user together with a media preview and editable caption; privacy has no default and interactions start unchecked. Do NOT use for inbox uploads or claim this proves the app passed audit. Permission/rate-limit errors stop the current posting attempt.' },
    { name: 'tiktok_upload', title: 'Upload a TikTok inbox draft', schema: tiktokUploadSchema, readOnly: false,
        description: 'Send a local video to the authorized TikTok account inbox with video.upload. Requires explicit approval for this media and expectedOpenId from sns_account_check. Validates media with ffprobe and uploads sequential FILE_UPLOAD chunks. Returns a durable requestId/publishId and processing or uncertain state; use tiktok_status. The user must open the TikTok inbox notification and finish as Only you, preserving caption and disclosures. Then use ego lite to edit and verify the saved cover before making that same post public. If cover editing is blocked, keep it private. This inbox delivery is NOT a published post. Reusing requestId returns its receipt without resubmission; changed arguments are rejected. Do not create another requestId after a timeout or lost response. No public URL hosting needed.' },
    { name: 'tiktok_publish', title: 'Direct-post a TikTok video', schema: tiktokPublishSchema, readOnly: false,
        description: '⚠️ HITL: never call without the user’s explicit approval for this post. Submit a local video via TikTok Direct Post (video.publish). For the standard publish workflow submit SELF_ONLY, then edit and verify the cover in ego lite before making the same post public in the browser; if cover editing is blocked, leave it private. This tool does not update an existing post or its visibility. The adapter supports other privacy levels but they bypass that workflow. Show media preview, editable caption, fresh tiktok_creator_info, account nickname, user-selected privacy and interactions, commercial/AI disclosures and Music Usage Confirmation before calling. Branded content also needs Branded Content Policy acceptance. Rechecks account/creator limits before sending. Unaudited clients are SELF_ONLY and TikTok also requires private accounts; audited public use requires direct_post_audited:true in the external client file after actual audit approval. Internal team-only upload utilities are ineligible for that audit; never claim this adapter alone meets TikTok review UX. Returns durable receipt; tiktok_status PUBLISH_COMPLETE confirms processing, not public visibility or the saved cover. Never blindly retry; reuse requestId after interruption.' },
    { name: 'tiktok_status', title: 'Check a TikTok upload receipt', schema: tiktokStatusSchema, readOnly: false,
        description: 'Refresh a channel-scoped durable TikTok upload receipt by requestId. Queries publish/status/fetch using its original publish_id and open_id and saves the remote status without resubmitting media. Distinguishes SEND_TO_USER_INBOX, PUBLISH_COMPLETE, FAILED and processing; an inbox draft is not publication and PUBLISH_COMPLETE for SELF_ONLY is still private, not completion of the browser cover and public steps. If initialization lost its response, returns submission_unknown with no guessed publish ID. Do NOT create a new upload to recover uncertainty. Requires the original account credentials and relevant posting scope; returns remote failure/status fields without upload URLs or tokens.' },
    { name: 'tiktok_videos', title: 'List TikTok public video metrics', schema: tiktokVideosSchema, readOnly: true,
        description: 'Read the authorized TikTok user\'s public videos and view/like/comment/share counts with Display API video.list. Returns videos, cursor and has_more; pass cursor for the next page. Does not return private posts, drafts, audience geography, watch-time analytics or comments. Requires video.list approval and user consent. Use for published-video feedback, not arbitrary-account research. Account mismatch, expired authorization and rate-limit errors return explicit failures.' },
];
export const TIKTOK_TOOLS = definitions.map(({ schema, readOnly, ...tool }) => ({
    ...tool, inputSchema: zodToJsonSchema(schema, { $refStrategy: 'none' }),
    annotations: readOnly ? { readOnlyHint: true, openWorldHint: true }
        : { readOnlyHint: false, destructiveHint: tool.name === 'tiktok_publish', idempotentHint: false, openWorldHint: true },
}));
